using System;
using System.Collections;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Text;

public static class EngineCenteredHud {
 static byte[] Bytes(ulong n){return BitConverter.GetBytes(n);} static byte[] I32(int n){return BitConverter.GetBytes(n);} static byte[] U32(uint n){return BitConverter.GetBytes(n);} static byte[] F32(float n){return BitConverter.GetBytes(n);}
 static void Put(EngineGame g,ulong a,byte[] before,byte[] after){g.Write(a,before,after);}
 static float Float(byte[] b,int p=0){return BitConverter.ToSingle(b,p);} static string X(ulong n){return n.ToString("X");}
 static Dictionary<string,object> Entry(object value){return (Dictionary<string,object>)value;}
 static ArrayList Items(Dictionary<string,object> d,string k){return (ArrayList)d[k];}
 static Dictionary<string,object> MakeCommand(ulong frame,ulong parent,int side,double pos,double offset,double oldPos,double oldOffset){return EngineJson.Obj("Frame",X(frame),"Parent",X(parent),"Side",side,"Position",pos,"Offset",offset,"OldPosition",oldPos,"OldOffset",oldOffset);}
 static void Save(string path,Dictionary<string,object> r){EngineJson.Write(path,r);}
 static void Signal(EngineGame g,ulong state,ulong owner,int request){if(g.U32(state+4)!=0)throw new Exception("HUD update is busy; run again.");Put(g,state,I32(0),I32(request));var flag=g.Bytes(owner+0x28,1);Put(g,owner+0x28,flag,new[]{(byte)(flag[0]|0x10)});}
 public static Dictionary<string,object> Run(string root,string action,int width,int height){
  if(action!="Enable"&&action!="Disable"&&action!="Status")throw new ArgumentException("Invalid centered HUD action.");
  SC2CampaignModeHook.ValidateTarget(width,height);double inset=SC2CampaignModeHook.HudInset(width,height);
  using(var g=new EngineGame("Cannot read HUD state.","Open exactly one StarCraft II campaign session first.")){
   var p=g.Game;ulong b=g.Base;int pid=p.Id;ulong gameUI=g.Ptr(b+SC2Addresses.Rva(0x4032368));if(gameUI==0||g.Ptr(gameUI)!=b+SC2Addresses.Rva(0x2D522A8))throw new Exception("Load a campaign mission before using the HUD helper.");
   ulong console=g.Ptr(gameUI+0xc60),owner=g.Ptr(gameUI+0xc68),world=g.Ptr(gameUI+0xc18),original=b+SC2Addresses.Rva(0x2D51C58);string path=Path.Combine(root,"hud-runtime-session.json");Dictionary<string,object> r=null;
   if(File.Exists(path)){var c=EngineJson.Read(path);if(g.Matches(c)&&EngineJson.Str(c,"Owner")==X(owner)){r=c;r["Commands"]=new ArrayList((ICollection)r["Commands"]);}}
   if(action=="Enable"){SC2CampaignGate.Require(pid,b);if(r!=null&&EngineJson.Int(r,"GateRevision")!=2)throw new Exception("Close StarCraft II before using the updated campaign restrictions.");}
   if(action=="Enable"&&r!=null&&(EngineJson.Str(r,"Console")!=X(console)||(EngineJson.Str(r,"WorldPanel")!=""&&EngineJson.Str(r,"WorldPanel")!=X(world)))){
    ulong oldState=EngineJson.Hex(r["State"]);if(g.U32(oldState+4)!=0)throw new Exception("Previous mission HUD update is still busy.");uint pending=g.U32(oldState);if(pending!=0)Put(g,oldState,U32(pending),U32(0));if(g.Ptr(owner)==EngineJson.Hex(r["VTable"]))Put(g,owner,Bytes(EngineJson.Hex(r["VTable"])),Bytes(original));r=null;
   }
   if(action=="Enable"){
    ulong device=g.Ptr(b+SC2Addresses.Rva(0x43D0E08)),resource=g.Ptr(device+0x80);uint packed=g.U32(resource+0x60);if((packed&0x3fff)!=width||((packed>>14)&0x3fff)!=height)throw new Exception("Activate your selected resolution before centering the HUD.");
    if(r!=null&&(EngineJson.Int(r,"TargetWidth")!=width||EngineJson.Int(r,"TargetHeight")!=height))throw new Exception("Close StarCraft II before changing resolution.");
    if(r==null||g.Ptr(owner)!=EngineJson.Hex(r["VTable"])){
     if(g.Ptr(owner)!=original||g.Ptr(console)!=b+SC2Addresses.Rva(0x2D62E98))throw new Exception("Unexpected console frame type; no changes made.");if(g.Ptr(original+0x148)!=b+SC2Addresses.Rva(0x16B53C0))throw new Exception("Layout callback mismatch.");
     byte[] expected={0x40,0x53,0x55,0x57,0x48,0x83,0xec,0x50,0x0f,0x29,0x74,0x24,0x40,0x49,0x8b,0xe8,0x66,0x41,0x0f,0x6e,0xf1,0x48,0x8b,0xf9,0xf3,0x0f,0x11,0x74,0x24,0x20,0x8b,0xda};var sig=g.Bytes(b+SC2Addresses.Rva(0x16BCFC0),expected.Length);if(!Equal(sig,expected))throw new Exception("Native anchor function signature mismatch.");
     var commands=new List<SC2HudHook.Command>();foreach(ulong frame in new[]{console,owner}){ulong parent=g.Ptr(frame+0x50);foreach(int side in new[]{1,3}){var a=g.Bytes(frame+0x68+(ulong)(16*side),16);ulong rel=BitConverter.ToUInt64(a,0);double pos=BitConverter.ToInt16(a,8)/2048.0;float off=Float(a,12);double np=side==1?0:1,no=side==1?inset:-inset;if(rel!=parent||pos!=np||(Math.Abs(off)>0.001&&Math.Abs(off-no)>0.001)||(BitConverter.ToUInt16(a,10)&4)!=0)throw new Exception("Console anchors differ from the verified default layout.");commands.Add(new SC2HudHook.Command{Frame=frame,Parent=parent,Side=side,Position=(float)np,Offset=(float)no,OldPosition=(float)pos,OldOffset=0});}}
     var prepared=SC2HudHook.Prepare(pid,owner,original,b+SC2Addresses.Rva(0x16BCFC0),commands.ToArray());var encoded=new ArrayList();foreach(var c in commands)encoded.Add(MakeCommand(c.Frame,c.Parent,c.Side,c.Position,c.Offset,c.OldPosition,c.OldOffset));r=EngineJson.Obj("GateRevision",2,"GamePid",pid,"Started",p.StartTime.ToString("o"),"Build",p.MainModule.FileVersionInfo.FileVersion,"TargetWidth",width,"TargetHeight",height,"Owner",X(owner),"Console",X(console),"OriginalVTable",X(original),"VTable",X(prepared.VTable),"Code",X(prepared.Code),"State",X(prepared.State),"Length",prepared.Length,"Commands",encoded);Save(path,r);if(g.Ptr(gameUI+0xc68)!=owner)throw new Exception("Mission UI changed before attachment.");Put(g,owner,Bytes(original),Bytes(prepared.VTable));
    }
    ulong state=EngineJson.Hex(r["State"]);if(g.U32(state)!=0||g.U32(state+4)!=0)throw new Exception("A HUD update is pending; return to the mission first.");
    if(!r.ContainsKey("WorldOffsetAddress")){
     world=g.Ptr(gameUI+0xc18);if(g.Ptr(world)!=b+SC2Addresses.Rva(0x2D6C370))throw new Exception("Unexpected world panel type.");var a=g.Bytes(world+0x88,16);if(BitConverter.ToUInt64(a,0)!=gameUI||BitConverter.ToInt16(a,8)!=2048||Float(a,12)!=-200||Float(g.Bytes(gameUI+0xbfc,4))!=200)throw new Exception("World viewport differs from the verified campaign layout.");if(g.U32(state+48)!=4)throw new Exception("Unexpected HUD command count.");var wc=MakeCommand(world,gameUI,2,1,0,1,-200);((ArrayList)r["Commands"]).Add(wc);r["WorldOffsetAddress"]=X(gameUI+0xbfc);r["WorldOffsetOriginal"]=200.0;r["WorldPanel"]=X(world);Save(path,r);var buf=new byte[40];Array.Copy(Bytes(world),0,buf,0,8);Array.Copy(Bytes(gameUI),0,buf,8,8);Array.Copy(I32(2),0,buf,16,4);Array.Copy(F32(1),0,buf,20,4);Array.Copy(F32(1),0,buf,28,4);Array.Copy(F32(-200),0,buf,32,4);Put(g,state+64+4*40,new byte[40],buf);Put(g,state+48,I32(4),I32(5));
    }
    if(!r.ContainsKey("MenuConsoleAnchor")){
     if(g.U32(state+48)!=5)throw new Exception("Unexpected HUD command count before menu alignment.");var menu=new List<Dictionary<string,object>>();ulong[] frames=new ulong[2];int i=0;foreach(ulong member in new ulong[]{0xc80,0xc88}){ulong f=g.Ptr(gameUI+member),parent=g.Ptr(f+0x50);if(f==0||parent==0||g.Ptr(f)!=original)throw new Exception("Unexpected menu anchor frame.");var a=g.Bytes(f+0x98,16);float off=Float(a,12);if(BitConverter.ToUInt64(a,0)!=parent||BitConverter.ToInt16(a,8)!=2048||(BitConverter.ToUInt16(a,10)&4)!=0||(Math.Abs(off)>0.001&&Math.Abs(off+inset)>0.001))throw new Exception("Menu anchors differ from the supported layout.");frames[i++]=f;menu.Add(MakeCommand(f,parent,3,1,-inset,1,0));}((ArrayList)r["Commands"]).AddRange(menu);r["MenuConsoleAnchor"]=X(frames[0]);r["MenuFullscreenAnchor"]=X(frames[1]);Save(path,r);var buf=new byte[80];for(i=0;i<2;i++){var e=menu[i];int ix=40*i;Array.Copy(Bytes(EngineJson.Hex(e["Frame"])),0,buf,ix,8);Array.Copy(Bytes(EngineJson.Hex(e["Parent"])),0,buf,ix+8,8);Array.Copy(I32(3),0,buf,ix+16,4);Array.Copy(F32(1),0,buf,ix+20,4);Array.Copy(F32((float)-inset),0,buf,ix+24,4);Array.Copy(F32(1),0,buf,ix+28,4);}SC2CampaignGate.Require(pid,b);Put(g,state+64+5*40,new byte[80],buf);Put(g,state+48,I32(5),I32(7));
    }
    if(g.Ptr(gameUI+0xc80)!=EngineJson.Hex(r["MenuConsoleAnchor"])||g.Ptr(gameUI+0xc88)!=EngineJson.Hex(r["MenuFullscreenAnchor"]))throw new Exception("Menu frames changed; reload the mission before reapplying.");if(g.U32(state+48)!=((ArrayList)r["Commands"]).Count)throw new Exception("HUD command state is incomplete; no further changes.");ulong property=EngineJson.Hex(r["WorldOffsetAddress"]);if(property!=gameUI+0xbfc)throw new Exception("Game UI changed; no viewport write.");var pb=g.Bytes(property,4);float value=Float(pb);if(value!=0&&value!=Convert.ToSingle(r["WorldOffsetOriginal"]))throw new Exception("World crop was changed by another source.");SC2CampaignGate.Require(pid,b);Put(g,property,pb,F32(0));SC2CampaignGate.Require(pid,b);r["RestoreRequested"]=false;Save(path,r);Signal(g,state,owner,1);Console.WriteLine("Centered console update queued. Return to the paused mission to let the game update its UI.");
   } else if(action=="Disable") {
    if(r==null||g.Ptr(owner)!=EngineJson.Hex(r["VTable"])){Console.WriteLine("No HUD wrapper is attached to this mission.");return null;}ulong state=EngineJson.Hex(r["State"]);uint pending=g.U32(state);if(pending!=0)Put(g,state,U32(pending),U32(0));if(r.ContainsKey("WorldOffsetAddress")){if(g.U32(state+48)!=((ArrayList)r["Commands"]).Count)throw new Exception("HUD command state is incomplete; no further changes.");ulong property=EngineJson.Hex(r["WorldOffsetAddress"]);if(property!=gameUI+0xbfc)throw new Exception("Game UI changed; no viewport restoration.");var pb=g.Bytes(property,4);float value=Float(pb);if(value!=0&&value!=Convert.ToSingle(r["WorldOffsetOriginal"]))throw new Exception("World crop was changed by another source.");Put(g,property,pb,F32(Convert.ToSingle(r["WorldOffsetOriginal"])));}r["RestoreRequested"]=true;Save(path,r);Signal(g,state,owner,2);Console.WriteLine("Original console anchors queued for restoration. Return to the mission, then run Status to detach the completed wrapper.");
   }
   if(r==null){Console.WriteLine("No centered HUD helper is recorded for this mission.");return null;}
   var stateBytes=g.Bytes(EngineJson.Hex(r["State"]),64);var framesOut=new ArrayList();foreach(var item in new[]{new object[]{"Console artwork",console},new object[]{"Console controls",owner}}){string name=(string)item[0];ulong addr=(ulong)item[1];var fb=g.Bytes(addr,0xc0);framesOut.Add(EngineJson.Obj("Name",name,"LeftOffset",Float(fb,0x84),"RightOffset",Float(fb,0xa4),"RectLeft",Float(fb,0xac),"RectRight",Float(fb,0xb4),"LayoutFlags",fb[0x28]));}
   bool attached=g.Ptr(owner)==EngineJson.Hex(r["VTable"]);if(action=="Status"&&EngineJson.Bool(r,"RestoreRequested")&&attached&&BitConverter.ToUInt32(stateBytes,0)==0&&BitConverter.ToUInt32(stateBytes,4)==0&&BitConverter.ToUInt32(stateBytes,12)>0){var f0=Entry(framesOut[0]);var f1=Entry(framesOut[1]);if(Math.Abs(Convert.ToDouble(f0["LeftOffset"]))<.001&&Math.Abs(Convert.ToDouble(f0["RightOffset"]))<.001&&Math.Abs(Convert.ToDouble(f1["LeftOffset"]))<.001&&Math.Abs(Convert.ToDouble(f1["RightOffset"]))<.001){Put(g,owner,Bytes(EngineJson.Hex(r["VTable"])),Bytes(original));attached=false;}}
   return EngineJson.Obj("GamePid",pid,"Attached",attached,"Pending",BitConverter.ToUInt32(stateBytes,0),"Busy",BitConverter.ToUInt32(stateBytes,4),"LayoutCallbacks",BitConverter.ToUInt32(stateBytes,8),"CompletedUpdates",BitConverter.ToUInt32(stateBytes,12),"SuccessfulAnchors",BitConverter.ToUInt32(stateBytes,16),"WorldCrop",Float(g.Bytes(gameUI+0xbfc,4)),"WorldBottom",Float(g.Bytes(g.Ptr(gameUI+0xc18)+0xb0,4)),"Frames",framesOut);
  }
 }
 static bool Equal(byte[] a,byte[] b){if(a.Length!=b.Length)return false;for(int i=0;i<a.Length;i++)if(a[i]!=b[i])return false;return true;}
}
